events.body:
I ran some mutation testing and found 3 live mutants besides https://github.com/bitcoin/bitcoin/pull/35793#discussion_r4338365979. These 3 move BIP54 enforcement by one block at activation.

I also published them at https://mutanthub.space/projects/bitcoin/bitcoin/pulls/35793, where they can be discussed.

<details>
<summary>src/validation.cpp (3)</summary>

<details>
<summary>Sigops limit enforced a block early</summary>

```diff
@@ -2519,7 +2519,7 @@ bool Chainstate::ConnectBlock(const CBlock& block, BlockValidationState& state,
     std::optional<CCheckQueueControl<CScriptCheck>> control;
     if (auto& queue = m_chainman.GetCheckQueue(); queue.HasThreads() && fScriptChecks) control.emplace(queue);
 
-    const bool enforce_bip54{DeploymentActiveAt(*pindex, m_chainman, Consensus::DEPLOYMENT_CONSENSUSCLEANUP)};
+    const bool enforce_bip54{DeploymentActiveAfter(pindex, m_chainman, Consensus::DEPLOYMENT_CONSENSUSCLEANUP)};
     std::vector<int> prevheights;
     CAmount nFees = 0;
     int nInputs = 0;
```
</details>

<details>
<summary>Timewarp skipped at activation block</summary>

```diff
@@ -4115,7 +4115,7 @@ static bool ContextualCheckBlockHeader(const CBlockHeader& block, BlockValidatio
         if (consensusParams.enforce_BIP94) {
             static_assert(MAX_TIMEWARP_TESTNET4 <= MAX_TIMEWARP_BIP54);
             max_timewarp = MAX_TIMEWARP_TESTNET4;
-        } else if (DeploymentActiveAfter(pindexPrev, chainman, Consensus::DEPLOYMENT_CONSENSUSCLEANUP)) {
+        } else if (DeploymentActiveAt(*pindexPrev, chainman, Consensus::DEPLOYMENT_CONSENSUSCLEANUP)) {
             max_timewarp = MAX_TIMEWARP_BIP54;
         }
         if (max_timewarp && block.GetBlockTime() < pindexPrev->GetBlockTime() - *max_timewarp) {
```
</details>

<details>
<summary>Coinbase locktime skipped at activation</summary>

```diff
@@ -4197,7 +4197,7 @@ static bool ContextualCheckBlock(const CBlock& block, BlockValidationState& stat
     }
 
     // Make sure the coinbase transaction is timelocked to the block's height.
-    if (nHeight > 0 && DeploymentActiveAfter(pindexPrev, chainman, Consensus::DEPLOYMENT_CONSENSUSCLEANUP)) {
+    if (nHeight > 0 && DeploymentActiveAt(*pindexPrev, chainman, Consensus::DEPLOYMENT_CONSENSUSCLEANUP)) {
         if (block.vtx[0]->nLockTime != static_cast<uint32_t>(nHeight - 1)) {
             return state.Invalid(BlockValidationResult::BLOCK_CONSENSUS, "bad-cb-locktime", "block height mismatch in coinbase nLockTime");
         }
```
</details>

